import sys, json; sys.path.insert(0,'/home/claude/skripty')
from stranka import stranka
O='/home/claude/dokuio.com/src/obsah/ch-it/'
P=lambda n,p:{'nazev':n,'popis':p}
K3=[('Inserite i dati','Ciò che non sapete lasciatelo vuoto – resterà una riga da completare a mano.'),('Controllate il testo','Ogni paragrafo si può modificare.'),('Scaricate e firmate','PDF o Word, gratis.')]
PRIV=('Salvate i miei dati?','No. Il documento è creato direttamente nel vostro browser; i dati non vengono inviati a un server.')
CO='Modello redatto secondo il Codice delle obbligazioni svizzero (CO).'
def d(slug, ident, nazev, nazevA, popis, kat, il, slova, title, desc, perex, obsahPopis, obsah, online, hodi, nehodi, po, faq, zakony, vt, vd, de, souv=None):
    landing={'title':title,'description':desc,'perex':perex,'obsahPopis':obsahPopis,'obsah':[P(*x) for x in obsah],'kroky':[P(*x) for x in K3],'online':online,'hodiSe':hodi,'nehodiSe':nehodi,'po':[P(*x) for x in po],'faq':[{'q':q,'a':a} for q,a in faq+[PRIV]],'zakony':zakony,'souvisejiciPopis':'Altri documenti, anch’essi gratuiti.'}
    t=title.replace('{rok}','2026')
    if not 70<=len(desc)<=170: print('DESC',slug,len(desc))
    if len(t)>70: print('TITLE',slug,len(t))
    if not 30<=len(vd)<=170: print('VD',slug,len(vd))
    if len(vt)>70: print('VT',slug,len(vt))
    assert len(faq)>=3, ('FAQ',slug)
    for w in ('modello','PDF','gratis'): assert w in t, (slug,w)
    txt=stranka('ch-it',slug,ident,nazev,nazevA,{'popis':popis,'kategorie':kat,'ilustrace':il,'slova':slova},souv or kat,landing,{'title':vt,'description':vd,'podnadpis':'Gratis · risultato in PDF e Word · pochi minuti'})
    txt=txt.replace("  souvisejici:", f"  protejsky: {json.dumps({'ch': de})},\n  souvisejici:",1)
    open(O+slug+'.ts','w').write(txt)

